<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{Delete,Edit,Plus,Refresh,Search}from'@element-plus/icons-vue';import{ElMessage,ElMessageBox}from'element-plus';import{deleteLogisticsConfig,getLogisticsConfigs}from'@/api/logistics';import type{LogisticsConfig}from'@/types/logistics';import LogisticsForm from'./components/LogisticsForm.vue';const loading=ref(false),list=ref<LogisticsConfig[]>([]),formRef=ref<InstanceType<typeof LogisticsForm>>();const query=reactive({keyword:'',status:undefined as number|undefined});const load=async()=>{loading.value=true;try{list.value=await getLogisticsConfigs(query)}finally{loading.value=false}};const reset=()=>{query.keyword='';query.status=undefined;load()};const remove=async(row:LogisticsConfig)=>{await ElMessageBox.confirm(`确认删除物流配置「${row.name}」吗？`,'提示',{type:'warning'});await deleteLogisticsConfig(row.uid!);ElMessage.success('删除成功');load()};onMounted(load)</script>
<template><div class="page-card"><div class="toolbar"><div class="filters"><h4>物流配置</h4><el-input v-model="query.keyword" placeholder="物流名称 / 编码" clearable style="width:210px"/><el-select v-model="query.status" placeholder="状态" clearable style="width:110px"><el-option label="启用" :value="1"/><el-option label="停用" :value="2"/></el-select><el-button type="primary" :icon="Search" @click="load">查询</el-button><el-button :icon="Refresh" @click="reset">重置</el-button></div><el-button v-perm="'POST:/admin/logistics/config/save'" type="primary" :icon="Plus" @click="formRef?.open()">新增配置</el-button></div><el-table v-loading="loading" :data="list"><el-table-column prop="name" label="物流公司" min-width="180"/><el-table-column prop="code" label="物流编码" min-width="150"/><el-table-column prop="tracking_url" label="查询地址" min-width="260" show-overflow-tooltip/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="sort" label="排序" width="80"/><el-table-column prop="remark" label="备注" min-width="180" show-overflow-tooltip/><el-table-column label="操作" width="110"><template #default="{row}"><el-icon class="op-icon is-edit" @click="formRef?.open(row)"><Edit/></el-icon><el-icon class="op-icon is-danger" @click="remove(row)"><Delete/></el-icon></template></el-table-column></el-table><LogisticsForm ref="formRef" @success="load"/></div></template><style scoped>.filters{display:flex;align-items:center;gap:12px}</style>
